<script setup lang="ts">import {Library} from '../types/domain';defineProps<{libraries:Library[];modelValue:number}>();defineEmits<{"update:modelValue":[value:number]}>()</script><template><label>光谱库<select aria-label="光谱库" :value="modelValue" @change="$emit('update:modelValue',Number(($event.target as HTMLSelectElement).value))"><option v-for="l in libraries" :key="l.id" :value="l.id">{{l.code}} / {{l.name}} · {{l.supported?'可解混':'病态/不支持'}}</option></select></label></template>
